    if b'jumb' in data or (b'c2pa' in data and b'claim' in data):
        print(f"   ❌ C2PA JUMBF structure detected")
    else:
        print(f"   ✅ No C2PA JUMBF structure")

    # Method 3: Check for AI XMP
    if b'CreatorTool' in data and (b'ChatGPT' in data or b'DALL' in data):
