        print(f"   ❌ trainedAlgorithmicMedia tag found")
    else:
        print(f"   ✅ No AI XMP metadata")

    # Method 4: For PNG, check for caBX chunks
    if fpath.suffix.lower() == '.png':
        if b'caBX' in data:
            print(f"   ❌ PNG caBX (C2PA) chunk found")
        else:
            print(f"   ✅ No PNG caBX chunks")

    # Method 5: For JPEG, check after FFD9 (end of image)
    if fpath.suffix.lower() in ['.jpg', '.jpeg']:
        last_ffd9 = data.rfind(b'\xFF\xD9')
        if last_ffd9 > 0 and last_ffd9 < len(data) - 2:
            trailer = data[last_ffd9+2:]
            if len(trailer) > 100:  # Significant trailer
                if b'c2pa' in trailer.lower() or b'jumb' in trailer:
                    print(f"   ❌ C2PA data in post-FFD9 trailer ({len(trailer)} bytes)")
                else:
                    print(f"   ⚠️  Non-empty trailer ({len(trailer)} bytes) but no C2PA")
            else:
                print(f"   ✅ Clean end-of-image (trailer: {len(trailer)} bytes)")

    # Confirm shop credit is intact
    if b'Roos Keramiek' in data:
        print(f"   ✅ Shop credit 'Roos Keramiek' preserved")
    else:
        print(f"   ⚠️  Shop credit not found (might be OK)")

print("\n" + "=" * 70)
print("VERIFICATION COMPLETE")
